check('Registered theme applies','returned 1' in api('theme_apply','{key:"test_ocean"}'))
api('title','{text:{text:"Theme test"}}');api('themed_body','{text:{text:"Themed body"}}');api('button','{label:{text:"Themed button"},callback:[{type:"function",function:"mdl_test:echo"}],payload:{}}');run('mdl:api/show')
check('Theme title styling survives setter',str(frame()['dialog']['title']['color'])=='aqua')
