# 2.0 typed chains, nested snapshots, observers and native action codec checks.
def chain(actions,payload=None):
 cmd('data modify storage mdl_test:chain args set value '+json.dumps({'callback':[],'payload':payload or {}}))
 for action in actions:cmd('data modify storage mdl_test:chain args.callback append value '+json.dumps(action))
 return cmd('execute as Tester run function mdl:api/actions with storage mdl_test:chain args')
cmd('scoreboard players set #chain mdl.tmp 0')
chain([{'type':'run_command','cmd':'scoreboard players set #chain mdl.tmp 2'},{'type':'run_command','cmd':'scoreboard players operation #chain mdl.tmp *= #ten mdl.sys'}])
check('Typed command actions execute in array order',score('#chain','mdl.tmp')==20)
chain([{'type':'function','function':'mdl_test:payload'}],{'n':19})
check('Function action inherits route payload',int(hook_value('action_payload.n'))==19)
chain([{'type':'function','function':'mdl_test:payload','payload':{'n':8}}],{'n':19})
check('Action-specific payload overrides shared payload',int(hook_value('action_payload.n'))==8)
cmd('scoreboard players set #chain mdl.tmp 0')
chain([{'type':'function','function':'mdl_test:nested'},{'type':'run_command','cmd':'scoreboard players add #chain mdl.tmp 1'}])
check('Nested chain preserves parent remainder',score('#chain','mdl.tmp')==11)
chain([{'type':'function','function':'mdl_test:nested'}]);check('Nested function result is restored for after hook',int(hook_value('action.result'))==7 and str(hook_value('action.action.function'))=='mdl_test:nested')
check('Dispatcher stack drains after nested calls',len(storage('mdl:dispatch','stack'))==0)
before=score('#hook_before_action','mdl.tmp');after=score('#hook_after_action','mdl.tmp')
chain([{'type':'run_command','cmd':'scoreboard players add #chain mdl.tmp 1'}])
check('Before and after hooks observe each action',score('#hook_before_action','mdl.tmp')==before+1 and score('#hook_after_action','mdl.tmp')==after+1)
