check('Before-action hook can cancel execution',score('#chain','mdl.tmp')==22 and int(hook_value('action.cancelled'))==1 and int(hook_value('action.result'))==0)
cmd('scoreboard players set #chain mdl.tmp 0')
chain([{'type':'run_command','cmd':'scoreboard players add #chain mdl.tmp 1'} for _ in range(65)])
check('Action chain bounded to 64 entries',score('#chain','mdl.tmp')==64)
chain([{'type':'not_supported'}])
check('Unsupported action reports zero result',int(hook_value('action.result'))==0)
chain([]);check('Empty callback array is a no-op',len(storage('mdl:dispatch','stack'))==0)
